function accountWidgetsV8(id){
 const tasks=accountTasks(id),docs=accountDocs(id).filter(d=>d.type==='file'),logs=DB.logs.filter(l=>l.accountId===id);
 return `<section class="card"><div class="card-head"><h2>Tasks &amp; Notes</h2></div>${tasks.slice(0,4).map(t=>`<a class="continue-item" href="#/accounts/${id}/tasks/${t.id}"><div class="grow"><strong>${esc(t.title)}</strong><p>${esc(t.kind)}${t.kind==='Task'?' · '+esc(t.status)+' · Due '+fmtDate(t.due):' · '+esc(t.description||'')}</p></div>${icon('chevron')}</a>`).join('')||empty('No tasks or notes yet','Add a follow-up or keep a note for this account.')}<div class="card-foot">${link('View all tasks & notes ('+tasks.length+')','#/accounts/'+id+'/tasks','link small')}${act('+ Add task or note','new-task',{accountId:id},'btn block mt')}</div></section>
 <section class="card"><div class="card-head"><h2>Documents</h2></div>${docs.slice(0,4).map(d=>`<a class="continue-item" href="#/accounts/${id}/documents"><div class="grow"><strong>${esc(d.name)}</strong><p>${esc(d.category||'Document')}</p></div>${icon('file')}</a>`).join('')||empty('No documents yet','Upload files from the Documents page.')}<div class="card-foot">${link('View all documents ('+docs.length+')','#/accounts/'+id+'/documents','link small')}</div></section>
 <section class="card"><div class="card-head"><h2>Activity</h2></div>${logs.slice(0,4).map(l=>`<div class="activity-row"><div class="grow"><strong>${esc(l.title)}</strong><p>${esc(l.description)}</p><small>${esc(l.author)} · ${stamp(l.at)}</small></div></div>`).join('')||empty('No activity yet','Saved actions will appear here.')}<div class="card-foot">${link('View all activity','#/accounts/'+id+'/log','link small')}</div></section>`;
}
const actionBeforeV8=handleAction;
handleAction=async function(action,d,el){if(action==='v8-edit-notes'){const a=account(d.id);if(!a)return;return openModal('Account Notes',field('Notes to keep with this account','notes',a.notes||'',{type:'textarea',rows:7}),act('Cancel','close-modal')+'<button type="submit" class="btn primary">Save notes</button>',{form:'v8-account-notes',data:{id:d.id}});}return actionBeforeV8(action,d,el);};
const formBeforeV8=handleForm;
handleForm=async function(form){if(form.dataset.form==='v8-account-notes'){const a=account(form.dataset.id);if(!a)return;const v=readForm(form);a.notes=v.notes;a.updated=now();logAction(a.id,'Account notes updated','Persistent account notes were updated.','account');persist();closeModal();render();return toast('Account notes saved');}return formBeforeV8(form);};
